using System.Globalization;using System.Windows;using Forms=System.Windows.Forms;
namespace SonicForge.App;
public partial class SettingsWindow:Window
{
 AppSettings _settings;
 public SettingsWindow(){InitializeComponent();_settings=AppSettings.Load();LoadValues();}
 void LoadValues(){OutputFolderBox.Text=_settings.OutputFolder;StartDbBox.Text=F(_settings.StartThresholdDb);StopDbBox.Text=F(_settings.StopThresholdDb);SilenceBox.Text=F(_settings.StopSilenceSeconds);ConfirmBox.Text=F(_settings.StartConfirmSeconds);PreRollBox.Text=F(_settings.PreRollSeconds);AutoThresholdCheck.IsChecked=_settings.AutomaticThresholdsEnabled;AutoMetadataCheck.IsChecked=_settings.AutoMetadata;AutoCoverCheck.IsChecked=_settings.AutoLoadCover;OpenEditorCheck.IsChecked=_settings.OpenTagEditorAfterRecording;PatternBox.Text=_settings.FileNamePattern;foreach(var item in MetadataSourceBox.Items.OfType<System.Windows.Controls.ComboBoxItem>())if((item.Content?.ToString()??"")==_settings.MetadataSource){MetadataSourceBox.SelectedItem=item;break;}MetadataSourceBox.SelectedIndex=Math.Max(0,MetadataSourceBox.SelectedIndex);}
 static string F(double v)=>v.ToString("0.##",CultureInfo.CurrentCulture);
 static bool D(string text,out double value)=>double.TryParse(text,NumberStyles.Float,CultureInfo.CurrentCulture,out value)||double.TryParse(text,NumberStyles.Float,CultureInfo.InvariantCulture,out value);
 void ChooseFolder_Click(object s,RoutedEventArgs e){using var d=new Forms.FolderBrowserDialog{Description="Standardordner für SonicForge-Aufnahmen",UseDescriptionForTitle=true,SelectedPath=OutputFolderBox.Text};if(d.ShowDialog()==Forms.DialogResult.OK)OutputFolderBox.Text=d.SelectedPath;}
 void Save_Click(object s,RoutedEventArgs e){if(!D(StartDbBox.Text,out var start)||!D(StopDbBox.Text,out var stop)||!D(SilenceBox.Text,out var silence)||!D(ConfirmBox.Text,out var confirm)||!D(PreRollBox.Text,out var pre)){System.Windows.MessageBox.Show(this,"Bitte gültige Zahlen eingeben.","Einstellungen",MessageBoxButton.OK,MessageBoxImage.Information);return;}if(silence<1||confirm<=0||pre<0){System.Windows.MessageBox.Show(this,"Stille muss mindestens 1 Sekunde betragen; Bestätigung muss größer 0 und Vorlauf mindestens 0 sein.");return;}_settings.OutputFolder=OutputFolderBox.Text.Trim();_settings.StartThresholdDb=start;_settings.StopThresholdDb=stop;_settings.StopSilenceSeconds=silence;_settings.StartConfirmSeconds=confirm;_settings.PreRollSeconds=pre;_settings.AutomaticThresholdsEnabled=AutoThresholdCheck.IsChecked==true;_settings.AutoMetadata=AutoMetadataCheck.IsChecked==true;_settings.AutoLoadCover=AutoCoverCheck.IsChecked==true;_settings.OpenTagEditorAfterRecording=OpenEditorCheck.IsChecked==true;_settings.MetadataSource=(MetadataSourceBox.SelectedItem as System.Windows.Controls.ComboBoxItem)?.Content?.ToString()??"Automatisch";_settings.FileNamePattern=string.IsNullOrWhiteSpace(PatternBox.Text)?"{Interpret} - {Titel}":PatternBox.Text.Trim();_settings.Save();StatusText.Text="Einstellungen gespeichert.";DialogResult=true;}
 void Reset_Click(object s,RoutedEventArgs e){_settings=new AppSettings();LoadValues();StatusText.Text="Standardwerte geladen. Zum Übernehmen speichern.";}
 void Cancel_Click(object s,RoutedEventArgs e)=>Close();
}
